<?php require __DIR__ . '/../partials/header.php'; ?>
<div class="card" style="max-width:700px;margin:0 auto;"><div class="card-header"><h1>Post Notice</h1><p>Send a message to sellers, vendors, or everyone.</p></div>
<?php if($generalErr):?><div class="alert alert-error"><?php echo e($generalErr);?></div><?php endif;?><?php if($successMsg):?><div class="alert alert-success"><?php echo e($successMsg);?></div><?php endif;?>
<form method="post" action="<?php echo e(url_for('admin','notices'));?>"><?php echo csrf_field();?><div class="field"><label for="message">Notice Message</label><textarea id="message" name="message" rows="4"><?php echo e($message);?></textarea></div><div class="field"><label for="target_role">To</label><select id="target_role" name="target_role"><option value="all" <?php echo $target_role==='all'?'selected':'';?>>All (Sellers + Vendors)</option><option value="seller" <?php echo $target_role==='seller'?'selected':'';?>>Sellers only</option><option value="vendor" <?php echo $target_role==='vendor'?'selected':'';?>>Vendors only</option></select></div><button class="btn btn-primary btn-block">Post Notice</button></form></div>
<div class="card"><div class="card-header"><h2>All Notices</h2></div><?php if(!$notices):?><p class="muted">No notices yet.</p><?php else:?><table class="data-table"><tr><th>ID</th><th>Message</th><th>To</th><th>By</th><th>Date</th></tr><?php foreach($notices as $n):?><tr><td>#<?php echo e($n['id']);?></td><td><?php echo e($n['message']);?></td><td><?php echo e($n['target_role']==='all'?'All':$n['target_role']);?></td><td><?php echo e($n['admin_name']);?></td><td class="small"><?php echo e($n['created_at']);?></td></tr><?php endforeach;?></table><?php endif;?></div>
